#include <iostream>
using namespace std;

int burn(int dist) {
    return dist * 5;
}

int burn(int dist, int cargo) {
    return dist * 5 + cargo * 3;
}

int main() {
    int dist, cargo;
    cin >> dist >> cargo;

    cout << "SIGMA: " << burn(dist) << endl;
    cout << "OMEGA: " << burn(dist, cargo) << endl;

    return 0;
}

